// ===== p236 : de vrais instruments pour les airs du jeu — échantillons enregistrés, joués à toutes les hauteurs.
// Violon : « violin » de gaijinbuzz (CC0) et « violin single note swell » de TheFlyFishingFilmmaker (CC BY 4.0) ; violoncelle et psaltérion : gaijinbuzz (CC0). Freesound.
// Le violon de synthèse reste en secours tant que les sons ne sont pas décodés. =====
const ECH236={b64:{},buf:{},pret:false};
Object.assign(ECH236.b64,{"vio_c4": "", "vio_d5": "", "vlc": "", "psal": ""});
const RAC236={vio:[['vio_c4',60.1],['vio_d5',73.8]],vlc:[['vlc',47.7]],psal:[['psal',60.1]]};
function charge236(){const c=typeof SND!=='undefined'&&SND.ctx;if(!c||ECH236.enc||!Object.keys(ECH236.b64).length)return;ECH236.enc=1;let n=0;const L=Object.keys(ECH236.b64);
 L.forEach(k=>{const s=atob(ECH236.b64[k]),u=new Uint8Array(s.length);for(let i=0;i<s.length;i++)u[i]=s.charCodeAt(i);c.decodeAudioData(u.buffer).then(b=>{ECH236.buf[k]=b;if(++n===L.length)ECH236.pret=true}).catch(()=>{if(++n===L.length)ECH236.pret=Object.keys(ECH236.buf).length>0})})}
setInterval(()=>{try{if(!ECH236.enc&&typeof SND!=='undefined'&&SND.ctx)charge236()}catch(e){}},1000);
// joue une note : l'échantillon le plus proche, transposé ; attaque douce, extinction à la fin de la durée
function ech236(inst,m,d,t,v){const c=sndPret();if(!c)return false;const R=RAC236[inst];if(!R)return false;let best=null,bd=1e9;R.forEach(([k,r])=>{if(ECH236.buf[k]&&Math.abs(m-r)<bd){bd=Math.abs(m-r);best=[k,r]}});if(!best)return false;
 const b=ECH236.buf[best[0]],s=c.createBufferSource();s.buffer=b;s.playbackRate.value=Math.pow(2,(m-best[1])/12);const g=c.createGain(),t0=c.currentTime+(t||0),dur=Math.min(d+.08,b.duration/s.playbackRate.value-.02);
 const k=v*(inst==='psal'?9:inst==='vlc'?10:8);g.gain.setValueAtTime(0,t0);g.gain.linearRampToValueAtTime(k,t0+(inst==='psal'?.005:.035));g.gain.setValueAtTime(k,t0+Math.max(.04,dur-.09));g.gain.linearRampToValueAtTime(0,t0+dur);
 s.connect(g);g.connect(SND.out);s.start(t0);s.stop(t0+dur+.02);return true}
{const v0=violon205;violon205=function(m,d,t,v){if(ECH236.pret&&ech236('vio',m,d,t,v))return;return v0.apply(this,arguments)}}
// l'air de cour se joue au psaltérion (cordes pincées, couleur ancienne) avec le violon ; la version pirate prend le violoncelle en bourdon
if(typeof joue217==='function'){const j0=joue217;joue217=function(N,nat,lim,vol,fin){if(nat==='cour'&&ECH236.pret){const c=sndPret();if(c){const M=lim?N.slice(0,lim):N;let t=.15;M.forEach(([m,d],i)=>{if(m){ech236('psal',m-12,d*.21,t,.03*(vol||1));if(i%2===0)ech236('vlc',m-24,d*.21*1.6,t,.022*(vol||1))}t+=d*.21})}}
  if(nat==='pirate'&&ECH236.pret){const c=sndPret();if(c){const M=lim?N.slice(0,lim):N;let t=.15;M.forEach(([m,d],i)=>{if(m&&i%4===0)ech236('vlc',m-24,d*.22*2,t,.03*(vol||1));t+=d*.22})}}
  return j0.apply(this,arguments)}}
